def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的颱風、災害資料與公共決策推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的路徑、雨風、地形、暴露、群體與政策選項。", f"整理證據：分開危害、暴露、脆弱度、損失與調適成本；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」能同時處理颱風資料與生活決策。", "排除誘答：檢查是否只看中心路徑、總損失、工程規模或單一成功案例，並找出遺漏的空間與群體。", "結論回查：確認預報時間、統計分母、地區尺度與方案限制一致；情境改變時重新評估。"]
    return {"id": f"question-social-content-geo-ac-iv-4-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ac-iv-4"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫颱風與生活探究情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ac-iv-4", "examPatternRefs": refs, "solutionStrategy": "先讀取颱風路徑與風雨資料，再分辨地方危害、暴露與脆弱度，最後比較工程、撤離與公平成本。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ac-iv-4-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
